const items = $input.all();
const clientName = 'MELOSMILE';
const niche = 'salud bucal y estética dental';

// Extract content from Notion pages
const posts = items.map(item => {
  const props = item.json.properties || {};
  const title = props.Title?.title?.[0]?.plain_text || props.Name?.title?.[0]?.plain_text || 'Sin título';
  const content = props.Content?.rich_text?.[0]?.plain_text || props.Description?.rich_text?.[0]?.plain_text || '';
  const platform = props.Platform?.select?.name || '';
  const format = props.Meta_Format?.select?.name || '';
  return { title, content, platform, format };
}).filter(p => p.content.length > 0);

const postsText = posts.map((p, i) => `${i+1}. [${p.platform}/${p.format}] ${p.title}: ${p.content.substring(0, 300)}`).join('\n\n');

const prompt = `Basado en los siguientes posts recientes de ${clientName} (${niche}), genera 5-10 ideas de contenido fresco. Para cada idea devuelve un objeto JSON con: title, description, format (Reel/Carousel/Story/Post), angles (array de strings).

Posts recientes:\n${postsText}`;

return [{ json: { prompt, clientName, niche } }];

const response = $json;
const content = (response.choices?.[0]?.message?.content || '').toString();
if (!content.trim()) return [{ json: { error: 'No content' } }];

// --- Extract JSON objects embedded in the numbered list the LLM produces ---
// The LLM returns blocks like: "1. { \"title\": ... }" then "2. { ... }"
// Strategy: find every { ... } block and parse it; fall back to line parser if none.

function parseBlockJSON(text) {
  const ideas = [];
  let idx = 0;
  while (idx < text.length) {
    const open = text.indexOf('{', idx);
    if (open === -1) break;
    // find matching closing brace balancing nested { }
    let depth = 0;
    let inStr = false;
    let close = -1;
    for (let i = open; i < text.length; i++) {
      const c = text[i];
      if (inStr) {
        if (c === '\\') { i++; continue; }
        if (c === '"') inStr = false;
        continue;
      }
      if (c === '"') { inStr = true; continue; }
      if (c === '{') depth++;
      else if (c === '}') { depth--; if (depth === 0) { close = i; break; } }
    }
    if (close === -1) break;
    const chunk = text.substring(open, close + 1);
    try {
      const obj = JSON.parse(chunk);
      if (obj && typeof obj === 'object' && (obj.title || obj.description || obj.angles || obj.format)) {
        ideas.push(obj);
      }
    } catch (e) {
      // not a valid JSON object block; skip
    }
    idx = close + 1;
  }
  return ideas;
}

function parseLineByLine(text) {
  const ideas = [];
  let current = null;
  for (const line of text.split('\n').map(l => l.trim()).filter(l => l)) {
    const numMatch = line.match(/^\d+[.)]\s*(.+)/);
    if (numMatch) {
      if (current && current.title) ideas.push(current);
      current = { title: numMatch[1].trim().replace(/^[{\"' 	]+|[}\"' 	]+$/g, ''), description: '', format: 'Post', angles: [] };
      continue;
    }
    if (current && line.toLowerCase().startsWith('description:')) {
      current.description = line.substring(line.indexOf(':') + 1).trim();
      continue;
    }
    if (current && line.toLowerCase().startsWith('format:')) {
      current.format = line.substring(line.indexOf(':') + 1).trim();
      continue;
    }
    if (current && line.toLowerCase().startsWith('angles:')) {
      const at = line.substring(line.indexOf(':') + 1).trim();
      current.angles = at.split(',').map(a => a.trim().replace(/^[\[\]"]|["\]]$/g, '')).filter(Boolean);
      continue;
    }
    if (current && current.title && line && !line.match(/^\d+[.)]/)) {
      current.description += (current.description ? ' ' : '') + line;
    }
  }
  if (current && current.title) ideas.push(current);
  return ideas;
}

let ideas = parseBlockJSON(content);
if (ideas.length === 0) ideas = parseLineByLine(content);

// Normalize
const VALID_FORMATS = ['Reel', 'Carousel', 'Story', 'Post'];
ideas = ideas
  .map(idea => ({
    title: String(idea.title || '').replace(/^[\s\"'{]+|[\s\"'}]+$/g, '').trim(),
    description: String(idea.description || idea.content || '').trim(),
    format: String(idea.format || 'Post').trim(),
    angles: Array.isArray(idea.angles) ? idea.angles.map(String) : []
  }))
  .filter(i => i.title.length > 0);

ideas.forEach(idea => {
  const known = VALID_FORMATS.find(k => idea.format.toLowerCase() === k.toLowerCase());
  idea.format = known || 'Post';
});

if (ideas.length === 0) return [{ json: { error: 'No ideas parsed' } }];

return ideas.map(idea => ({
  json: {
    action: 'create',
    target_db: 'PUBLICACIONES',
    properties: {
      Title: { title: [{ text: { content: idea.title } }] },
      Status: { select: { name: 'ideation' } },
      Meta_Format: { select: { name: idea.format } },
      Content: { rich_text: [{ text: { content: idea.description } }] }
    }
  }
}));
